build_track_render_caches.source:
// build_track_render_caches @ 0x433220 (thiscall-shaped member, ret 0x10)

#include <string.h>
#include <stddef.h>

#include "audio_system.h"
#include "fringe_object.h"
#include "object_render_types.h"
#include "subgame_runtime.h"
#include "track_attachment_types.h"
#include "segment_cache.h"

int report_errorf(const char* format, ...);
int debug_report_stub(const char* format, ...);

#define RUNTIME_CELL_BASE_OFFSET ((int)offsetof(cRSubGame, runtime_cells))
#define RUNTIME_CELL_OFFSET(field) \
    ((int)offsetof(cRSubGame, runtime_cells[0][0].field))

void SegmentCache::build_track_render_caches(tColour skirt_color)
{
    enum {
        MAX_INDEX_COUNT_LANE =
            ((int)offsetof(SegmentCache, max_index_counts)
                - (int)offsetof(SegmentCache, max_vertex_counts)) / sizeof(int),
        SHARED_VERTEX_BUFFER_LANE =
            ((int)offsetof(SegmentCache, shared_vertex_buffers)
                - (int)offsetof(SegmentCache, max_vertex_counts)) / sizeof(int),
        SHARED_INDEX_BUFFER_LANE =
            ((int)offsetof(SegmentCache, shared_index_buffers)
                - (int)offsetof(SegmentCache, max_vertex_counts)) / sizeof(int),
    };

    int row_index;
    tColourSmall white_color;
    int work_value;
    int cache_row;
    int cells_remaining;
    int row_mod;
    void* locked_vertices;
    void* locked_indices;
    int saved_cell_offset;
    int vertex_counts[TRACK_RENDER_CACHE_FAMILY_COUNT];
    int index_counts[TRACK_RENDER_CACHE_FAMILY_COUNT];

    white_color.noop_this_constructor();
    skirt_color_bgra.operator=(skirt_color);
    *(int*)&white_color = -1;
    ((AudioBackend*)this)->noop_runtime_ai();

    row_index = 0;
    if (owner_subgame->runtime_row_count > 0) {
        int cell_offset = 0;
        do {
            row_mod = row_index % 24;
            if (row_mod == 0) {
                cache_row = row_index / 24;

                int* slot_row_base =
                    (int*)&slots[cache_row][TRACK_RENDER_CACHE_FLOOR].cache_row_base;

                memset(index_counts, 0, sizeof(index_counts));

                build_cache_row_base = (float)cache_row * 24.0f;

                memset(vertex_counts, 0, sizeof(vertex_counts));
                work_value = TRACK_RENDER_CACHE_FAMILY_COUNT;
                do {
                    *slot_row_base = *(int*)&build_cache_row_base;
                    slot_row_base += sizeof(TrackRenderCacheSlot) / sizeof(int);
                    --work_value;
                } while (work_value != 0);
            }

            cells_remaining =
                sizeof(owner_subgame->runtime_cells[0])
                / sizeof(owner_subgame->runtime_cells[0][0]);
            do {
                int fringe_offset = cell_offset + RUNTIME_CELL_OFFSET(fringe_front);
                work_value = 4;
                do {
                    Fringe* fringe_object =
                        *(Fringe**)((char*)owner_subgame + fringe_offset);
                    if (fringe_object != 0) {
                        append_track_cache_object(
                            row_index,
                            fringe_object->object,
                            (Vector3*)((char*)&owner_subgame->runtime_cells[0][0].position
                                + cell_offset),
                            (ObjectRenderVertex*)shared_vertex_buffers[
                                TRACK_RENDER_CACHE_FRINGE],
                            &vertex_counts[TRACK_RENDER_CACHE_FRINGE],
                            (unsigned short*)shared_index_buffers[
                                TRACK_RENDER_CACHE_FRINGE],
                            &index_counts[TRACK_RENDER_CACHE_FRINGE],
                            max_vertex_counts[TRACK_RENDER_CACHE_FRINGE],
                            max_index_counts[TRACK_RENDER_CACHE_FRINGE],
                            *(unsigned int*)&skirt_color_bgra,
                            0);

                        slots[cache_row][TRACK_RENDER_CACHE_FRINGE]
                            .object->group_texture_refs[0] =
                            (*(Fringe**)((char*)owner_subgame + fringe_offset))
                                ->object->facequads[0].texture_ref;
                        *(Fringe**)((char*)owner_subgame + fringe_offset) = 0;
                    }
                    fringe_offset += 4;
                    --work_value;
                } while (work_value != 0);

                int flags = *(int*)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(lane_and_flags));
                if ((flags & SUBLOC_FLAG_WARNING_CACHE_FAMILY) != 0
                    && (flags & SUBLOC_FLAG_UNCACHED_BODY)
                        == SUBLOC_FLAG_UNCACHED_BODY) {
                    append_track_cache_object(
                        row_index,
                        *(Object**)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(object)),
                        (Vector3*)((char*)&owner_subgame->runtime_cells[0][0].position
                            + cell_offset),
                        (ObjectRenderVertex*)shared_vertex_buffers[
                            TRACK_RENDER_CACHE_WARNING],
                        &vertex_counts[TRACK_RENDER_CACHE_WARNING],
                        (unsigned short*)shared_index_buffers[
                            TRACK_RENDER_CACHE_WARNING],
                        &index_counts[TRACK_RENDER_CACHE_WARNING],
                        max_vertex_counts[TRACK_RENDER_CACHE_WARNING],
                        max_index_counts[TRACK_RENDER_CACHE_WARNING],
                        *(unsigned int*)&white_color,
                        1);

                    slots[cache_row][TRACK_RENDER_CACHE_WARNING]
                        .object->group_texture_refs[0] =
                        (*(Object**)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(object)))
                            ->facequads[0].texture_ref;
                    *(int*)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(lane_and_flags))
                        &= ~SUBLOC_FLAG_UNCACHED_BODY;
                } else if (((cRSubLoc*)((char*)owner_subgame + cell_offset
                                   + RUNTIME_CELL_BASE_OFFSET))
                                   ->IsFloor()
                    && ((*(int*)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(lane_and_flags))
                        & SUBLOC_FLAG_UNCACHED_BODY) == SUBLOC_FLAG_UNCACHED_BODY)) {
                    if ((*(int*)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(lane_and_flags))
                        & SUBLOC_FLAG_CACHE_FAMILY_SWAPPED)
                        == SUBLOC_FLAG_CACHE_FAMILY_SWAPPED) {
                        append_track_cache_object(
                            row_index,
                            *(Object**)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(object)),
                            (Vector3*)((char*)&owner_subgame->runtime_cells[0][0].position
                                + cell_offset),
                            (ObjectRenderVertex*)shared_vertex_buffers[
                                TRACK_RENDER_CACHE_SLIDE],
                            &vertex_counts[TRACK_RENDER_CACHE_SLIDE],
                            (unsigned short*)shared_index_buffers[
                                TRACK_RENDER_CACHE_SLIDE],
                            &index_counts[TRACK_RENDER_CACHE_SLIDE],
                            max_vertex_counts[TRACK_RENDER_CACHE_SLIDE],
                            max_index_counts[TRACK_RENDER_CACHE_SLIDE],
                            *(unsigned int*)&white_color,
                            1);

                        slots[cache_row][TRACK_RENDER_CACHE_SLIDE]
                            .object->group_texture_refs[0] =
                            (*(Object**)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(object)))
                                ->facequads[0].texture_ref;
                    } else {
                        append_track_cache_object(
                            row_index,
                            *(Object**)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(object)),
                            (Vector3*)((char*)&owner_subgame->runtime_cells[0][0].position
                                + cell_offset),
                            (ObjectRenderVertex*)shared_vertex_buffers[
                                TRACK_RENDER_CACHE_FLOOR],
                            &vertex_counts[TRACK_RENDER_CACHE_FLOOR],
                            (unsigned short*)shared_index_buffers[
                                TRACK_RENDER_CACHE_FLOOR],
                            &index_counts[TRACK_RENDER_CACHE_FLOOR],
                            max_vertex_counts[TRACK_RENDER_CACHE_FLOOR],
                            max_index_counts[TRACK_RENDER_CACHE_FLOOR],
                            *(unsigned int*)&white_color,
                            1);

                        slots[cache_row][TRACK_RENDER_CACHE_FLOOR]
                            .object->group_texture_refs[0] =
                            (*(Object**)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(object)))
                                ->facequads[0].texture_ref;
                    }
                    *(int*)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(lane_and_flags))
                        &= ~SUBLOC_FLAG_UNCACHED_BODY;
                } else if (((cRSubLoc*)((char*)owner_subgame + cell_offset
                                   + RUNTIME_CELL_BASE_OFFSET))
                                   ->IsSlide()
                    && ((*(int*)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(lane_and_flags))
                        & SUBLOC_FLAG_UNCACHED_BODY) == SUBLOC_FLAG_UNCACHED_BODY)) {
                    if ((*(int*)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(lane_and_flags))
                        & SUBLOC_FLAG_CACHE_FAMILY_SWAPPED)
                        == SUBLOC_FLAG_CACHE_FAMILY_SWAPPED) {
                        append_track_cache_object(
                            row_index,
                            *(Object**)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(object)),
                            (Vector3*)((char*)&owner_subgame->runtime_cells[0][0].position
                                + cell_offset),
                            (ObjectRenderVertex*)shared_vertex_buffers[
                                TRACK_RENDER_CACHE_FLOOR],
                            &vertex_counts[TRACK_RENDER_CACHE_FLOOR],
                            (unsigned short*)shared_index_buffers[
                                TRACK_RENDER_CACHE_FLOOR],
                            &index_counts[TRACK_RENDER_CACHE_FLOOR],
                            max_vertex_counts[TRACK_RENDER_CACHE_FLOOR],
                            max_index_counts[TRACK_RENDER_CACHE_FLOOR],
                            *(unsigned int*)&white_color,
                            1);

                        slots[cache_row][TRACK_RENDER_CACHE_FLOOR]
                            .object->group_texture_refs[0] =
                            (*(Object**)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(object)))
                                ->facequads[0].texture_ref;
                    } else {
                        append_track_cache_object(
                            row_index,
                            *(Object**)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(object)),
                            (Vector3*)((char*)&owner_subgame->runtime_cells[0][0].position
                                + cell_offset),
                            (ObjectRenderVertex*)shared_vertex_buffers[
                                TRACK_RENDER_CACHE_SLIDE],
                            &vertex_counts[TRACK_RENDER_CACHE_SLIDE],
                            (unsigned short*)shared_index_buffers[
                                TRACK_RENDER_CACHE_SLIDE],
                            &index_counts[TRACK_RENDER_CACHE_SLIDE],
                            max_vertex_counts[TRACK_RENDER_CACHE_SLIDE],
                            max_index_counts[TRACK_RENDER_CACHE_SLIDE],
                            *(unsigned int*)&white_color,
                            1);

                        slots[cache_row][TRACK_RENDER_CACHE_SLIDE]
                            .object->group_texture_refs[0] =
                            (*(Object**)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(object)))
                                ->facequads[0].texture_ref;
                    }
                    *(int*)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(lane_and_flags))
                        &= ~SUBLOC_FLAG_UNCACHED_BODY;
                } else if (((cRSubLoc*)((char*)owner_subgame + cell_offset
                                   + RUNTIME_CELL_BASE_OFFSET))
                                   ->IsRamp()
                    && ((*(int*)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(lane_and_flags))
                        & SUBLOC_FLAG_UNCACHED_BODY) == SUBLOC_FLAG_UNCACHED_BODY)) {
                    append_track_cache_object(
                        row_index,
                        *(Object**)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(object)),
                        (Vector3*)((char*)&owner_subgame->runtime_cells[0][0].position
                            + cell_offset),
                        (ObjectRenderVertex*)shared_vertex_buffers[
                            TRACK_RENDER_CACHE_RAMP],
                        &vertex_counts[TRACK_RENDER_CACHE_RAMP],
                        (unsigned short*)shared_index_buffers[
                            TRACK_RENDER_CACHE_RAMP],
                        &index_counts[TRACK_RENDER_CACHE_RAMP],
                        max_vertex_counts[TRACK_RENDER_CACHE_RAMP],
                        max_index_counts[TRACK_RENDER_CACHE_RAMP],
                        *(unsigned int*)&white_color,
                        0);

                    slots[cache_row][TRACK_RENDER_CACHE_RAMP]
                        .object->group_texture_refs[0] =
                        (*(Object**)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(object)))
                            ->facequads[0].texture_ref;
                    *(int*)((char*)owner_subgame + cell_offset + RUNTIME_CELL_OFFSET(lane_and_flags))
                        &= ~SUBLOC_FLAG_UNCACHED_BODY;
                }

                cell_offset += sizeof(cRSubLoc);
                --cells_remaining;
            } while (cells_remaining != 0);

            saved_cell_offset = cell_offset;
            if (row_mod == 23 || row_index == owner_subgame->runtime_row_count - 1) {
                int* max_vertices = max_vertex_counts;
                Object** object_ref =
                    &slots[cache_row][TRACK_RENDER_CACHE_FLOOR].object;
                int family_index = 0;

                do {
                    (*object_ref)->render_buffers->vertex_buffer->vtbl->Lock(
                        (*object_ref)->render_buffers->vertex_buffer,
                        0,
                        (*max_vertices * 3) << 3,
                        &locked_vertices,
                        0);
                    (*object_ref)->index_buffer->buffer->vtbl->Lock(
                        (*object_ref)->index_buffer->buffer,
                        0,
                        max_vertices[MAX_INDEX_COUNT_LANE] << 1,
                        &locked_indices,
                        0);

                    memcpy(locked_vertices, (void*)max_vertices[SHARED_VERTEX_BUFFER_LANE],
                        (*max_vertices * 3) << 3);
                    memcpy(locked_indices, (void*)max_vertices[SHARED_INDEX_BUFFER_LANE],
                        max_vertices[MAX_INDEX_COUNT_LANE] << 1);

                    (*object_ref)->render_buffers->vertex_buffer->vtbl->Unlock(
                        (*object_ref)->render_buffers->vertex_buffer);
                    (*object_ref)->index_buffer->buffer->vtbl->Unlock(
                        (*object_ref)->index_buffer->buffer);

                    (*object_ref)->grouped_vertex_count = vertex_counts[family_index];
                    (*object_ref)->group_primitive_counts[0] = index_counts[family_index] / 3;
                    (*object_ref)->vertex_count = vertex_counts[family_index];

                    object_ref = (Object**)((char*)object_ref + sizeof(TrackRenderCacheSlot));
                    ++max_vertices;
                    ++family_index;
                } while (family_index < TRACK_RENDER_CACHE_FAMILY_COUNT);

                cell_offset = saved_cell_offset;
            }

            ++row_index;
        } while (row_index < owner_subgame->runtime_row_count);
    }

    next_cache_row_z = 0.0f;
    next_cache_row_index = 0;

    int family_index = 0;
    do {
        int max_vertices_seen = 0;
        int max_indices_seen = 0;
        int cache_rows = owner_subgame->runtime_row_count / 24;

        if (cache_rows > 0) {
            Object** object_ref = &slots[0][family_index].object;
            do {
                Object* object = *object_ref;
                if (object->vertex_count > max_vertices_seen)
                    max_vertices_seen = object->vertex_count;

                int index_count = object->group_primitive_counts[0] * 4;
                if (index_count > max_indices_seen)
                    max_indices_seen = index_count;

                object_ref += sizeof(slots[0]) / sizeof(*object_ref);
                --cache_rows;
            } while (cache_rows != 0);
        }

        const char* cache_name;
        switch (family_index) {
        case TRACK_RENDER_CACHE_FLOOR:
            cache_name = "Floor";
            break;
        case TRACK_RENDER_CACHE_SLIDE:
            cache_name = "Slide";
            break;
        case TRACK_RENDER_CACHE_WARNING:
            cache_name = "Warn";
            break;
        case TRACK_RENDER_CACHE_RAMP:
            cache_name = "Ramp";
            break;
        case TRACK_RENDER_CACHE_FRINGE:
            cache_name = "Fringe";
            break;
        }

        debug_report_stub(
            "Max Cache Type=%s Vertices=%i   Indices=%i\n",
            cache_name,
            max_vertices_seen,
            max_indices_seen);
        ++family_index;
    } while (family_index < TRACK_RENDER_CACHE_FAMILY_COUNT);
}

create_golb.source:
// create_golb @ 0x415280 (thiscall, ret 0xc)
// cRSubGolb::Create(cRSubGoldy*, int, int): link a projectile slot, seed its
// spawn position and velocity from Goldy's shoot-flag family, then install
// the sprite, vapour, or path-search presentation path used by update_golb_ai.

#include "bod_ai_dispatch.h"
#include "game_root.h"
#include "golb.h"
#include "sprite.h"
#include "subgame_runtime.h"
#include "vapour.h"
#include "vector3.h"

typedef unsigned int DWORD;

typedef Vector3 Vec3;

int report_errorf(char* format, ...);
int gRMathRand2();

void cRSubGolb::Create(cRSubGoldy* player_, int spawn_selector, int shot_slot_index)
{
    // Only the laser family consumes this pointer; both laser spawn branches
    // define it before kind 1 resets the trail. It shares a native stack slot
    // with spawn_selector after the selector is dead.
    float* vapour_z_floor;
    skip_one_tick = 0;
    slug_bounce_armed = 0;

    BodNode* body = this;
    g_game->active_bod_list.add_bod(body);

    owner_player = player_;
    DWORD kind_flags = player_->shoot_flags;
    if ((kind_flags & 7) != 0) {
        kind = 0;
    } else if ((kind_flags & 0x18) != 0) {
        kind = 1;
    } else if ((kind_flags & 0x60) != 0) {
        kind = 2;
    }

    source_matrix.Identity();

    cRSubGoldy* spawn_player = owner_player;
    Vec3* position = &flight_transform.position;
    state = 1;
    *position = spawn_player->transform.position;
    Vec3 half_forward = spawn_player->transform.basis_forward * 0.5f;
    *position += half_forward;

    cRSubGoldy* player = owner_player;
    DWORD shoot_flags = player->shoot_flags;
    if ((shoot_flags & 5) == 0) {
        if ((shoot_flags & 2) != 0) {
            if (spawn_selector == 2) {
                Vec3* source = &player->presentation.snail_hotspots_world[
                    SNAIL_HOTSPOT_BLASTER_LEFT_FIRE];
                *position = *source;
                position->x += 0.5f;
            } else if (spawn_selector == 1) {
                Vec3* source = &player->presentation.snail_hotspots_world[
                    SNAIL_HOTSPOT_BLASTER_RIGHT_FIRE];
                *position = *source;
                position->x -= 0.5f;
            }
            velocity = Vec3(0.0f, 0.0f, player->velocity.z + 1.0f);
            goto after_default_launch_family;
        }

        if ((shoot_flags & 0x18) == 0) {
            if ((shoot_flags & 0x60) == 0) {
                if ((shoot_flags & 0x29) != 0) {
                    velocity = Vec3(0.0f, 0.0f, player->velocity.z + 1.0f);
                    goto after_default_launch_family;
                }

                if ((shoot_flags & 0x52) != 0) {
                    velocity = Vec3(0.0f, 0.0f, player->velocity.z + 1.0f);
                    if (spawn_selector == 2)
                        position->x += 0.5f;
                    else
                        position->x -= 0.5f;
                }
                goto after_default_launch_family;
            }

            {
                Vec3* source = &player->presentation.snail_hotspots_world[
                    SNAIL_HOTSPOT_ROCKET_BASE];
                *position = *source;
                velocity = Vec3(0.0f, 0.0f, player->velocity.z + 0.60000002f);
            }
            goto after_default_launch_family;
        }

        {
            if (spawn_selector == 2) {
                Vec3* source = &player->presentation.snail_hotspots_world[
                    SNAIL_HOTSPOT_LASER_LEFT];
                *position = *source;
                if (player->transform.basis_forward.z > 0.0f)
                    vapour_z_floor =
                        &player->presentation.snail_hotspots_world[
                            SNAIL_HOTSPOT_LASER_LEFT].z;
                else
                    vapour_z_floor = 0;
            } else {
                Vec3* source = &player->presentation.snail_hotspots_world[
                    SNAIL_HOTSPOT_LASER_RIGHT];
                *position = *source;
                if (player->transform.basis_forward.z > 0.0f)
                    vapour_z_floor =
                        &player->presentation.snail_hotspots_world[
                            SNAIL_HOTSPOT_LASER_LEFT].z;
                else
                    vapour_z_floor = 0;
            }
            velocity = Vec3(0.0f, 0.0f, player->velocity.z + 1.0f);
            skip_one_tick = 1;
        }
        goto after_default_launch_family;

after_default_launch_family:
        ;
    } else {
        if (spawn_selector == 3) {
            *position = player->presentation.snail_hotspots_world[
                SNAIL_HOTSPOT_BLASTER_LEFT_FIRE];
        } else if (spawn_selector == 2) {
            *position = player->presentation.snail_hotspots_world[
                SNAIL_HOTSPOT_BLASTER_RIGHT_FIRE];
        } else if (spawn_selector == 1) {
            *position = player->presentation.snail_hotspots_world[
                SNAIL_HOTSPOT_BLASTER_TOP_FIRE];
        }

        if ((player->shoot_flags & 4) != 0) {
            if (spawn_selector == 3) {
                Vec3 launch_velocity(0.1f, 0.0f, player->velocity.z + 1.0f);
                float spawn_x = position->x + 0.5f;
                velocity = launch_velocity;
                position->x = spawn_x;
            } else if (spawn_selector == 2) {
                velocity = Vec3(-0.1f, 0.0f, player->velocity.z + 1.0f);
                position->x -= 0.5f;
            } else {
                velocity = Vec3(0.0f, 0.0f, player->velocity.z + 1.0f);
            }
        } else {
            velocity = Vec3(0.0f, 0.0f, player->velocity.z + 1.0f);
        }
    }

    if (kind == 1) {
        velocity.x += velocity.x;
        velocity.y += velocity.y;
        velocity.z += velocity.z;
    }
    if (kind == 2) {
        velocity.x *= 0.80000001f;
        velocity.y *= 0.80000001f;
        velocity.z *= 0.80000001f;
    }

    direction = velocity;

    switch (kind) {
        case 2: {
            lifetime = 0.0f;
            lifetime_step = game->subgame_rate * 0.027777776f;
            rocket_owner_shot = this;
            spin = 0.0f;
            spin_step = 0.20943952f;
            homing_target_object = 0;

            g_game->active_bod_list.add_bod(&tertiary_body);

            this->shot_slot_index = shot_slot_index;
            ContactTargetEntry* found =
                game->enemy_manager.Find(*position);
            if (found) {
                ContactTargetObject* object = found->object;
                homing_target_object = object;
                if (!found->kind)
                    object->list_flags |= BOD_FLAG_SUPPRESS_CONTACT;
                homing_target = found->position;
                homing_blend = 0.0f;
                homing_blend_step = 0.033333335f;
            }
            break;
        }
        case 1: {
            lifetime = 0.0f;
            lifetime_step = game->subgame_rate * 0.041666668f;
            vapour_owner_shot = this;

            BodNode* node = &vapour;
            int& trail_flags = node->list_flags;
            BodNode* anchor = &g_game->subgame.golb_vapour_list_head;
            if ((trail_flags & BOD_FLAG_LINKED) != 0) {
                report_errorf("List ADDafter");
            } else {
                node->list_prev = anchor;
                node->list_next = anchor->list_next;
                anchor->list_next = node;
                if (node->list_next)
                    node->list_next->list_prev = node;
                trail_flags |= BOD_FLAG_LINKED;
            }

            vapour.ReSet(vapour_z_floor);
            vapour.color.store_color4f(1.0f, 1.0f, 1.0f, 0.99000001f);
            this->shot_slot_index = shot_slot_index;
            vapour.Add(flight_transform);
            ((BodAiDispatch*)&vapour)->update_bod_ai();
            break;
        }
        case 0: {
            lifetime = 0.0f;
            lifetime_step = game->subgame_rate * 0.041666668f;
            render_sprite = g_sprite_manager.New(
                owner_player->player_slot,
                130,
                -1,
                -1);
            render_sprite->flags |= SPRITE_FLAG_GAMEPLAY_OWNED;
            render_sprite->progress = 0.0f;
            render_sprite->progress_step = 0.0f;
            render_sprite->gravity_step = 0.0f;

            tColour color;
            render_sprite->color =
                *color.Set(1.0f, 1.0f, 1.0f, 1.0f);
            render_sprite->size_start = 0.49000001f;
            render_sprite->size_end = 0.49000001f;
            Vec3* sprite_position = (Vec3*)&render_sprite->position;
            *sprite_position = *position;
            render_sprite->facing_angle =
                ((float)gRMathRand2() - 16384.0f)
                * 0.0000610351562f * 3.1415927f;
            render_sprite->facing_angle_step =
                game->subgame_rate * 0.58177644f;
            this->shot_slot_index = shot_slot_index;
            break;
        }
    }

    if (owner_player->follow_state.active == 1
        && owner_player->follow_state.vertical_offset < 0.5f) {
        path_follow.active = 1;
        path_follow.template_record = owner_player->follow_state.template_record;
        path_follow.source_cell = owner_player->follow_state.source_cell;
        path_follow.sample_index = owner_player->follow_state.sample_index;
        path_follow.progress = owner_player->follow_state.progress;
        path_follow.vertical_offset = 0.0f;
        path_follow.output_position = owner_player->follow_state.output_position;
        path_follow.shot = this;
        path_entry_z_latch = owner_player->follow_state.output_position.z;
    } else {
        path_follow.active = 0;
        path_entry_z_latch = -1.0f;
    }

    path_factor = velocity.Magnitude();
    previous_flight_transform.position = flight_transform.position;

    ((BodAiDispatch*)this)->update_bod_ai();
}

