    if (is_key_down(0x2a) || is_key_down(0x36)) {
        result -= 0x20;
        repeat_code = result;
    }

after_letters:
    if (is_key_down(0x39)) {
        result = ' ';
        repeat_code = result;
    }
    if (is_key_down(0x0b)) {
        result = '0';
