static __forceinline void initialize_route_stars(cRGalaxy* galaxy, int galaxy_index, int star_group_offset, int& star_index)
{
        for (; star_index < galaxy->route_names[galaxy_index].star_count; ++star_index) {
            galaxy->route_slots[galaxy->record_count].record.route_name_index = galaxy_index;
            galaxy->route_slots[galaxy->record_count].record.map_x_bits =
                g_galaxy_route_points[
                    star_group_offset
                    + star_index * 10 / galaxy->route_names[galaxy_index].star_count
                    + 1].x_bits;
            galaxy->route_slots[galaxy->record_count].record.map_y_bits =
                g_galaxy_route_points[
                    star_group_offset
                    + star_index * 10 / galaxy->route_names[galaxy_index].star_count
                    + 1].y_bits;
            galaxy->route_slots[galaxy->record_count].record.map_z_bits = 0;

            char missing_label[128];
            sprintf(missing_label, "LEVEL %i MISSING", galaxy->record_count);
            Rstrcpy(
                galaxy->route_slots[galaxy->record_count].record.detail_text, missing_label);
            Rstrcpy(
                galaxy->route_slots[galaxy->record_count].record.description_text,
                missing_label);
            ++galaxy->record_count;
        }

}

