static __forceinline void apply_setjetpack(cRSnail* object, int target_state)
{
    int selected_state = object->jetpack_channel.selected_state;
    bool immediate = true;
    if (selected_state != target_state) {
        if (selected_state == 4) {
            object->jetpack_channel.SetAnimation(
                1, 1, OBJECT_ANIMATION_MODE_ONCE_REVERSE);
            immediate = false;
            g_sound_effect_manager.Play(26);
        }

        if (target_state != 0) {
            if (target_state == 4) {
                object->jetpack_channel.SetAnimation(1, immediate, target_state);
                object->jetpack_channel.SetAnimation(
                    0, 0, OBJECT_ANIMATION_MODE_UNCHANGED);
                g_sound_effect_manager.Play(16);
            }
        } else {
            object->jetpack_channel.SetAnimation(
                ANIM_MANAGER_HIDE_ANIMATION_ID,
                0,
                OBJECT_ANIMATION_MODE_UNCHANGED);
        }

        object->jetpack_channel.selected_state = target_state;
    }
}

